import com.sun.tools.javac.api.JavacTool;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.TreeScanner;
import javax.tools.*;
import java.io.*;
import java.net.*;
import java.util.*;

public class JcTreeDump {
    public static void main(String[] args) throws Exception {
        JavaCompiler c = JavacTool.create();
        JavaFileObject f = new SimpleJavaFileObject(URI.create("string:///T.java"), JavaFileObject.Kind.SOURCE) {
            public CharSequence getCharContent(boolean ignore) {
                return "import lombok.NonNull;\n" +
                       "public record T(@NonNull int [] a, int @NonNull [] b, int [] @NonNull [] c) {}\n" +
                       "@interface NonNull {}\n";
            }
        };
        JavacTask task = (JavacTask) c.getTask(null, null, null, Arrays.asList("-proc:none"), null, Arrays.asList(f));
        for (JCTree t : task.parse()) dump(t, 0);
    }

    static void dump(JCTree t, int depth) {
        for (int i = 0; i < depth; i++) System.out.print("  ");
        System.out.print(t == null ? "null" : t.getClass().getSimpleName());
        if (t instanceof JCTree.JCVariableDecl) {
            JCTree.JCVariableDecl v = (JCTree.JCVariableDecl) t;
            System.out.print(" name=" + v.name);
        }
        if (t instanceof JCTree.JCAnnotatedType) {
            JCTree.JCAnnotatedType a = (JCTree.JCAnnotatedType) t;
            System.out.print(" anns=" + a.annotations + " underlying=" + a.underlyingType.getClass().getSimpleName());
        }
        if (t instanceof JCTree.JCArrayTypeTree) {
            System.out.print(" elem=" + ((JCTree.JCArrayTypeTree) t).elemtype.getClass().getSimpleName());
        }
        if (t instanceof JCTree.JCAnnotation) {
            System.out.print(" type=" + ((JCTree.JCAnnotation) t).annotationType);
        }
        System.out.println();
        t.accept(new TreeScanner() {
            public void scan(JCTree child) {
                if (child != null) dump(child, depth + 1);
            }
        });
    }
